import json,glob,collections,sys
res=collections.defaultdict(list)
byid={}
for f in glob.glob('*.ndjson'):
    for line in open(f):
        r=json.loads(line)
        byid[r['id']]=r
        res[r['resourceType']].append(r)
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
# accessioning map
acc={}
for b in res['Basic']:
    acc[ext(b,'accession')]=b
pats={p['id']:p for p in res['Patient']}
def subj(r):
    s=r.get('subject') or r.get('patient') or r.get('for')
    if s: return s['reference'].split('/')[-1]
    return None
def et(r): return ext(r,'event-time') or ''
out=collections.defaultdict(list)
for t,rs in res.items():
    if t in ('Patient','Basic'): continue
    for r in rs:
        out[subj(r)].append(r)
target=sys.argv[1] if len(sys.argv)>1 else None
for pid,p in sorted(pats.items()):
    if target and pid!=target: continue
    print('='*100)
    print(pid, p['name'][0]['text'], p['birthDate'], p['gender'], 'MRN', p['identifier'][0]['value'])
    for r in sorted(out[pid],key=et):
        t=r['resourceType']; rid=r['id']
        pre=f"  [{et(r)[:16]}] {t}/{rid}"
        if t=='EpisodeOfCare':
            print(pre, 'start',r['period']['start'], r['type'][0]['text'])
        elif t=='Condition':
            print(pre, r['code']['text'],'| recorded',r.get('recordedDate'),'| recorder',r.get('recorder',{}).get('display'))
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            a=(r.get('identifier') or [{}])[0].get('value')
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            print(pre, r['code']['text'],'|',r['status'],'| coll',r.get('effectiveDateTime'),'| issued',r.get('issued'),'| val',r.get('valueString'),'| acc',a,'| spec',sp, ('| note '+notes) if notes else '')
            s=byid.get(sp)
            if s:
                print('       spec label:',ext(s,'label-name'),ext(s,'label-mrn'),ext(s,'label-dob'),'accid',s.get('accessionIdentifier',{}).get('value'),'collected',s.get('collection',{}).get('collectedDateTime'),'collector',s.get('collection',{}).get('collector',{}).get('display'),'subj',subj(s))
            b=acc.get(a)
            if b:
                print('       accession entry',b['id'],':',ext(b,'patient-name'),ext(b,'patient-mrn'),ext(b,'patient-dob'),'received',ext(b,'received'))
            else:
                print('       accession entry: NONE for',a)
        elif t=='Specimen':
            pass
        elif t=='MedicationAdministration':
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            print(pre, r['status'],'|',r.get('effectiveDateTime'),'|',r.get('dosage',{}).get('text'),'| perf',[x['actor']['display'] for x in r.get('performer',[])], ('| note '+notes) if notes else '')
        elif t=='MedicationDispense':
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            print(pre, r.get('status'),'|',r['medicationCodeableConcept']['text'] if 'medicationCodeableConcept' in r else '','| qty',r.get('quantity'),'| daysSupply',r.get('daysSupply'),'| handed',r.get('whenHandedOver'),'|',[d.get('text') for d in r.get('dosageInstruction',[])],('| note '+notes) if notes else '')
        elif t=='DocumentReference':
            print(pre, r['type']['text'],'| date',r.get('date'),'| author',[a['display'] for a in r.get('author',[])],'| role',ext(r,'author-role'))
            for ln in r['description'].split('\n'):
                print('       |',ln)
        elif t=='AllergyIntolerance':
            print(pre, r['code']['text'],'| reaction',json.dumps(r.get('reaction')))
        elif t=='Task':
            print(pre,'TASK',r['status'],r['code']['coding'][0]['code'],r.get('description'),r.get('focus'))
        else:
            print(pre,json.dumps(r)[:300])
