import json,glob,collections
R=collections.defaultdict(dict)
for f in glob.glob('*.ndjson'):
    for line in open(f):
        r=json.loads(line); R[r['resourceType']][r['id']]=r
def ext(r,n):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+n):
            return [v for k,v in e.items() if k.startswith('value')][0]
pat={p['id']:(p['identifier'][0]['value'],p['birthDate'],p['name'][0]['text']) for p in R['Patient'].values()}
acc={ext(b,'accession'):b for b in R['Basic'].values()}
for o in R['Observation'].values():
    subj=o['subject']['reference'].split('/')[-1]
    sp=R['Specimen'].get(o.get('specimen',{}).get('reference','').split('/')[-1])
    a=(o.get('identifier') or [{}])[0].get('value')
    b=acc.get(a)
    prob=[]
    if sp is None: prob.append('no spec')
    else:
        smrn,sdob=ext(sp,'label-mrn'),ext(sp,'label-dob')
        if (smrn,sdob)!=(pat[subj][0],pat[subj][1]): prob.append(f'label {smrn}/{sdob} vs chart {pat[subj][0]}/{pat[subj][1]}')
        if sp['subject']['reference'].split('/')[-1]!=subj: prob.append('spec subject '+sp['subject']['reference'])
        if sp.get('accessionIdentifier',{}).get('value')!=a: prob.append('accid mismatch')
    if b is None: prob.append('no accession entry')
    else:
        if (ext(b,'patient-mrn'),ext(b,'patient-dob'))!=(pat[subj][0],pat[subj][1]):
            prob.append(f"accession {ext(b,'patient-name')} {ext(b,'patient-mrn')}/{ext(b,'patient-dob')}")
    if prob: print(subj,pat[subj][2],o['id'],o['code']['text'],o.get('effectiveDateTime'),'|','; '.join(prob))
print('--- unused accession entries / dup accessions')
used=set((o.get('identifier') or [{}])[0].get('value') for o in R['Observation'].values())
for k,b in acc.items():
    if k not in used: print('unused',k,ext(b,'patient-name'),ext(b,'patient-mrn'))
print('--- non-final obs')
for o in R['Observation'].values():
    if o['status']!='final': print(o['subject']['reference'],o['id'],o['status'],o['code']['text'],o.get('effectiveDateTime'),[n['text'] for n in o.get('note',[])])
