import json,glob,collections,datetime as dt
R=collections.defaultdict(list)
for f in glob.glob('*.ndjson'):
    for line in open(f): r=json.loads(line); R[r['resourceType']].append(r)
def d(s): return dt.date.fromisoformat(s[:10])
def addm(date,m):
    y=date.year+(date.month-1+m)//12; mo=(date.month-1+m)%12+1
    day=min(date.day,[31,29 if y%4==0 and (y%100!=0 or y%400==0) else 28,31,30,31,30,31,31,30,31,30,31][mo-1])
    return dt.date(y,mo,day)
pats={p['id']:p['name'][0]['text'] for p in R['Patient']}
ma=collections.defaultdict(list)
for m in R['MedicationAdministration']:
    ma[m['subject']['reference'].split('/')[-1]].append((m['effectiveDateTime'][:10],m['status']))
rpr=collections.defaultdict(list)
for o in R['Observation']:
    if 'RPR' in o['code']['text']:
        rpr[o['subject']['reference'].split('/')[-1]].append((o['effectiveDateTime'][:10],o['status'],o['id']))
cond=collections.defaultdict(list)
for c in R['Condition']:
    cond[c['subject']['reference'].split('/')[-1]].append((c['recordedDate'][:10],c['code']['text']))
ep={e['patient']['reference'].split('/')[-1]:(e['id'],e['period']['start']) for e in R['EpisodeOfCare']}
EV=dt.date(2026,9,24)
for pid,name in sorted(pats.items(),key=lambda x:x[1]):
    doses=sorted([x for x in ma[pid] if x[1]=='completed'])
    print(f"{name:20s} {pid} ep {ep[pid][0]} dx {ep[pid][1]} | cond {cond[pid]} | doses {[x[0] for x in doses]}")
    if not doses: print('    untreated'); continue
    first=d(doses[0][0])
    st=' '.join(t for _,t in cond[pid]).lower()
    months=[6,12,24] if ('late' in st or 'unknown' in st) else [6,12]
    for m in months:
        due=addm(first,m); lo=due-dt.timedelta(30); hi=due+dt.timedelta(30)
        hits=[x for x in sorted(rpr[pid]) if lo<=d(x[0])<=hi]
        print(f"    {m}mo due {due} win {lo}..{hi} closed={hi<EV} hits={hits}")
